-- QA only: every fixture and financial movement is rolled back.
BEGIN;
SELECT set_config('request.headers',jsonb_build_object('x-govrp-world-generation',(SELECT value->>'generation_id' FROM public.system_settings WHERE key='world_runtime'))::text,true);
DO $test$
DECLARE admin uuid:=gen_random_uuid();citizen uuid:=gen_random_uuid();other uuid:=gen_random_uuid();c uuid;a uuid;a2 uuid;b uuid;acct uuid;k uuid:=gen_random_uuid();r jsonb;again jsonb;denied boolean;before_total numeric;after_total numeric;before_stock numeric;spent numeric;n integer;
BEGIN
 INSERT INTO auth.users(id,email) VALUES(admin,'qa-integrated-'||admin||'@example.invalid'),(citizen,'qa-integrated-'||citizen||'@example.invalid'),(other,'qa-integrated-'||other||'@example.invalid');
 UPDATE public.profiles SET full_name='Cidadão de QA',username='qa'||left(replace(id::text,'-',''),12),character_gender='male',onboarding_completed=true,onboarding_step='completed' WHERE id IN(admin,citizen,other);
 INSERT INTO private.platform_admins(user_id) VALUES(admin);
 PERFORM set_config('request.jwt.claim.sub',admin::text,true);
 PERFORM public.set_admin_development_mode('total',NULL,true);
 c:=public.save_public_competition(NULL,NULL,jsonb_build_object('name','Concurso Promotor QA','role','Promotor','vacancies',1,'notice_url','https://example.invalid/edital.pdf','forms_url','https://forms.gle/qa','registration_starts_at',now()-interval '1 hour','registration_ends_at',now()+interval '1 hour','exam_starts_at',now()+interval '2 hours','exam_ends_at',now()+interval '3 hours'));
 PERFORM public.get_public_competition_admin(c);
 PERFORM public.transition_public_competition(c,1,'published');
 PERFORM set_config('request.jwt.claim.sub',citizen::text,true);
 denied:=false;BEGIN PERFORM public.get_public_competition_admin(c);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Citizen accessed admin exam data';END IF;
 denied:=false;BEGIN UPDATE public.profiles SET role='Promotor' WHERE id=citizen;EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Direct role assignment bypassed competition';END IF;
 a:=public.register_public_competition(c);IF a IS DISTINCT FROM public.register_public_competition(c) THEN RAISE EXCEPTION 'Enrollment is not idempotent';END IF;
 denied:=false;BEGIN PERFORM public.get_public_competition_exam(c);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Exam opened early';END IF;
 PERFORM set_config('request.jwt.claim.sub',other::text,true);a2:=public.register_public_competition(c);
 UPDATE public.public_competitions SET registration_starts_at=now()-interval '4 hours',registration_ends_at=now()-interval '3 hours',exam_starts_at=now()-interval '1 hour',exam_ends_at=now()+interval '1 hour' WHERE id=c;
 PERFORM set_config('request.jwt.claim.sub',citizen::text,true);IF public.get_public_competition_exam(c)<>'https://forms.gle/qa' THEN RAISE EXCEPTION 'Enrolled candidate cannot open exam';END IF;
 PERFORM set_config('request.jwt.claim.sub',admin::text,true);
 denied:=false;BEGIN PERFORM public.decide_public_competition(a,true,true,true,'Critérios e identidade conferidos.');EXCEPTION WHEN OTHERS THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Approval before exam ended';END IF;
 UPDATE public.public_competitions SET exam_ends_at=now()-interval '1 minute' WHERE id=c;
 denied:=false;BEGIN PERFORM public.decide_public_competition(a,true,false,true,'Critérios e identidade conferidos.');EXCEPTION WHEN OTHERS THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Approval without identity confirmation';END IF;
 r:=public.decide_public_competition(a,true,true,true,'Critérios e identidade conferidos.');
 IF r->>'status'<>'approved' OR (SELECT role FROM public.profiles WHERE id=citizen)<>'Promotor' OR NOT EXISTS(SELECT 1 FROM public.public_careers WHERE profile_id=citizen AND application_id=a) THEN RAISE EXCEPTION 'Career not awarded atomically';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.notifications WHERE user_id=citizen AND metadata->>'application_id'=a::text AND (metadata->>'competition_approved')::boolean) THEN RAISE EXCEPTION 'Approval popup absent';END IF;
 PERFORM public.decide_public_competition(a,true,true,true,'Repetição da confirmação administrativa.');
 IF (SELECT count(*) FROM public.notifications WHERE user_id=citizen AND type='role_changed' AND metadata->>'new_role'='Promotor')<>1 THEN RAISE EXCEPTION 'Approval notification duplicated';END IF;
 denied:=false;BEGIN PERFORM public.decide_public_competition(a2,true,true,true,'Critérios e identidade conferidos.');EXCEPTION WHEN OTHERS THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Vacancies exceeded';END IF;
 PERFORM public.decide_public_competition(a2,false,true,false,'Pontuação insuficiente para aprovação.');
 PERFORM public.transition_public_competition(c,(SELECT version FROM public.public_competitions WHERE id=c),'results','https://example.invalid/results.pdf');
 PERFORM public.transition_public_competition(c,(SELECT version FROM public.public_competitions WHERE id=c),'finished');
 PERFORM set_config('request.jwt.claim.sub',citizen::text,true);IF NOT public.justice_has_role(ARRAY['Promotor']) THEN RAISE EXCEPTION 'Career prosecutor lacks justice access';END IF;
 IF EXISTS(SELECT 1 FROM public.institutional_terms WHERE profile_id=citizen) THEN RAISE EXCEPTION 'Competition created presidential mandate';END IF;
 -- A real company account and production, entirely confined to this transaction.
 INSERT INTO public.businesses(owner_id,business_type_id,name,status) VALUES(citizen,'pecuaria','Produção QA','active') RETURNING id INTO b;
 SELECT bank_account_id INTO acct FROM public.businesses WHERE id=b;
 IF acct IS NULL THEN INSERT INTO public.accounts(account_kind,business_id,account_number,balance) VALUES('business',b,'QA-'||b,0) RETURNING id INTO acct;UPDATE public.businesses SET bank_account_id=acct WHERE id=b;END IF;
 INSERT INTO public.business_inventory(business_id,resource_code,quantity,unit_cost,selling_price,available_for_sale) VALUES(b,'milk',100,2,6,true) ON CONFLICT(business_id,resource_code) DO UPDATE SET quantity=100,available_for_sale=true;
 PERFORM set_config('request.jwt.claim.sub',admin::text,true);
 UPDATE public.government_finances SET treasury_balance=1000000 WHERE id=1;
 SELECT (SELECT sum(balance) FROM public.accounts)+(SELECT treasury_balance FROM public.government_finances WHERE id=1) INTO before_total;
 PERFORM public.fund_national_market(1000,k);PERFORM public.fund_national_market(1000,k);
 IF (SELECT balance FROM public.accounts WHERE account_kind='national_market')<>1000 THEN RAISE EXCEPTION 'Budget funding duplicated';END IF;
 PERFORM set_config('request.jwt.claim.sub',other::text,true);denied:=false;
 BEGIN PERFORM public.sell_national_production(b,'milk',gen_random_uuid());EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Unauthorized supplier sold production';END IF;
 PERFORM set_config('request.jwt.claim.sub',citizen::text,true);k:=gen_random_uuid();r:=public.sell_national_production(b,'milk',k);again:=public.sell_national_production(b,'milk',k);
 IF (r->>'quantity')::numeric<>100 OR r->>'id' IS DISTINCT FROM again->>'id' THEN RAISE EXCEPTION 'Purchase quantity/idempotency failed: %',r;END IF;
 IF (SELECT quantity FROM public.business_inventory WHERE business_id=b AND resource_code='milk')<>0 OR (SELECT quantity FROM public.national_market_stock WHERE resource_code='milk')<>100 THEN RAISE EXCEPTION 'Stock not transferred';END IF;
 SELECT (SELECT sum(balance) FROM public.accounts)+(SELECT treasury_balance FROM public.government_finances WHERE id=1) INTO after_total;
 IF before_total<>after_total THEN RAISE EXCEPTION 'Money not conserved: % vs %',before_total,after_total;END IF;
 spent:=private.consume_national_market(current_date,1000);
 IF spent<=0 OR (SELECT quantity FROM public.national_market_stock WHERE resource_code='milk')<>0 THEN RAISE EXCEPTION 'Daily national consumption failed';END IF;
 IF private.consume_national_market(current_date,1000)<>0 THEN RAISE EXCEPTION 'Daily consumption duplicated';END IF;
 SELECT (SELECT sum(balance) FROM public.accounts)+(SELECT treasury_balance FROM public.government_finances WHERE id=1) INTO after_total;
 IF before_total<>after_total THEN RAISE EXCEPTION 'Consumption created/destroyed money';END IF;
 r:=public.get_national_production_catalog(b);IF jsonb_array_length(r->'purchases')<>1 THEN RAISE EXCEPTION 'Supplier history missing';END IF;
 RAISE NOTICE 'PASS: competition lifecycle, auth, exam timing, atomic career, notification, vacancies, prosecutor access, budget, supplier authorization, stock, idempotency, consumption, money conservation';
END $test$;
ROLLBACK;
